export const MODEL = [{"table": "M_Date", "emoji": "📅", "desc": "Central date/calendar table. Must be marked as a Date Table in Model View. Connect to every other table via their date column.", "note": "Mark as Date Table: right-click → Mark as date table → select Date column.", "usedIn": ["time", "finance", "hr", "sales", "operations", "inventory", "customerservice", "dynamic", "marketing"], "cols": [{"name": "Date", "type": "Date", "source": "formula", "desc": "One row per calendar day. Primary key — connect all fact tables here."}, {"name": "Year", "type": "Integer", "source": "formula", "desc": "Calendar year (e.g. 2024). Used in YoY and multi-year comparisons."}, {"name": "Month", "type": "Integer", "source": "formula", "desc": "Month number 1–12. Used in seasonality and rolling window calculations."}, {"name": "MonthNumber", "type": "Integer", "source": "formula", "desc": "Month number 1–12, same as Month — used in seasonality index formulas."}, {"name": "MonthKey", "type": "Integer", "source": "formula", "desc": "YYYYMM format (e.g. 202403). Unique per month — used in monthly average calculations."}, {"name": "WeekNumber", "type": "Integer", "source": "formula", "desc": "ISO week number 1–53. Required for WTD and same-week-last-year formulas."}, {"name": "DayOfWeek", "type": "Integer", "source": "formula", "desc": "1=Sunday, 7=Saturday (DAX default). Used in weekday/weekend revenue splits."}, {"name": "IsPublicHoliday", "type": "Boolean", "source": "formula", "desc": "TRUE if the day is a public/bank holiday. Populate from a holiday reference list in Power Query."}, {"name": "MonthName", "type": "Text", "source": "recommended", "desc": "Full month name (January, February…). Use for axis labels on charts."}, {"name": "MonthShort", "type": "Text", "source": "recommended", "desc": "Abbreviated month name (Jan, Feb…). Useful for compact visuals."}, {"name": "Quarter", "type": "Integer", "source": "recommended", "desc": "Quarter number 1–4. Used for QTD labels and quarter-level reporting."}, {"name": "QuarterName", "type": "Text", "source": "recommended", "desc": "Q1, Q2, Q3, Q4. Use on chart axes and in slicer labels."}, {"name": "DayName", "type": "Text", "source": "recommended", "desc": "Monday, Tuesday… Used in day-of-week analysis charts."}, {"name": "IsWeekend", "type": "Boolean", "source": "recommended", "desc": "TRUE for Saturday/Sunday. Simplifies weekday vs weekend filters."}, {"name": "FiscalYear", "type": "Integer", "source": "recommended", "desc": "Fiscal year number — adjust start month in Power Query to match your year-end."}, {"name": "FiscalQuarter", "type": "Integer", "source": "recommended", "desc": "Fiscal quarter 1–4, offset by your fiscal year start month."}, {"name": "YearMonth", "type": "Text", "source": "recommended", "desc": "'2024-03' format. Useful for sorting month labels chronologically on axes."}]}, {"table": "F_Sales", "emoji": "💰", "desc": "Core transactional table. One row per order line. The central fact table that connects to M_Products, M_Date, Customers, and Reps.", "note": "If you have one row per order (not per line), remove ProductID and Qty — Sale and Qty can stay at order level.", "usedIn": ["generic", "sales", "customer", "product", "inventory", "marketing", "time", "dynamic"], "cols": [{"name": "OrderID", "type": "Text", "source": "formula", "desc": "Unique order identifier. Use DISTINCTCOUNT(F_Sales[OrderID]) to count transactions."}, {"name": "CustomerID", "type": "Text", "source": "formula", "desc": "Foreign key to a Customers dimension table. Drives all customer-level analysis."}, {"name": "ProductID", "type": "Text", "source": "formula", "desc": "Foreign key to M_Products table. Drives all product-level analysis."}, {"name": "RepID", "type": "Text", "source": "formula", "desc": "F_Sales rep identifier. Use for rep performance leaderboards and quota attainment."}, {"name": "Sale", "type": "Currency", "source": "formula", "desc": "Net sale amount for the line item after discounts. Primary revenue measure — referenced as F_Sales[Sale] in all revenue formulas."}, {"name": "Qty", "type": "Integer", "source": "formula", "desc": "Units sold per line. Consolidated from Quantity and Qty — one column used for all volume analysis including inventory velocity, product ranking, and sales totals."}, {"name": "COGS", "type": "Currency", "source": "formula", "desc": "Cost of goods sold for the line. Required for gross margin and GMROI calculations."}, {"name": "Discount", "type": "Decimal", "source": "formula", "desc": "Discount rate applied (0.0 to 1.0). Used in average discount rate analysis."}, {"name": "RevenueType", "type": "Text", "source": "formula", "desc": "'New', 'Renewal', or 'Upsell'. Enables revenue quality split analysis."}, {"name": "SalesCost", "type": "Currency", "source": "formula", "desc": "F_Sales team cost attributable to this transaction. Used in CAC calculation."}, {"name": "OrderDate", "type": "Date", "source": "recommended", "desc": "Date the order was placed. Connect to M_Date[Date] for time intelligence."}, {"name": "CustomerName", "type": "Text", "source": "recommended", "desc": "Customer display name. Shown in top customer tables and leaderboards."}, {"name": "ProductName", "type": "Text", "source": "recommended", "desc": "Product display name. Shown in product rankings and charts."}, {"name": "Region", "type": "Text", "source": "recommended", "desc": "Geographic region or territory. Enables regional sales analysis."}, {"name": "SalesChannel", "type": "Text", "source": "recommended", "desc": "'Online', 'Direct', 'Partner' etc. Enables channel mix analysis."}, {"name": "Margin", "type": "Currency", "source": "recommended", "desc": "Revenue minus COGS. Pre-calculated margin column for faster performance."}]}, {"table": "M_Products", "emoji": "📦", "desc": "Product master/dimension table. One row per product. Connect to F_Sales via ProductID.", "note": "Keep one row per product — never include transactional data here. Relate to F_Sales[ProductID].", "usedIn": ["product", "inventory"], "cols": [{"name": "ProductID", "type": "Text", "source": "recommended", "desc": "Primary key. Must match F_Sales[ProductID] exactly for the relationship to work."}, {"name": "ProductName", "type": "Text", "source": "formula", "desc": "Full product name — used in RANKX labels and Top 5 CONCATENATEX strings."}, {"name": "Category", "type": "Text", "source": "recommended", "desc": "Product category or department. Enables category-level filtering and comparison."}, {"name": "SubCategory", "type": "Text", "source": "recommended", "desc": "Product sub-category. Enables drill-down from Category in matrix visuals."}, {"name": "ListPrice", "type": "Currency", "source": "recommended", "desc": "Standard list price. Compare against F_F_Sales[Sale] to calculate realised discount."}, {"name": "CostPrice", "type": "Currency", "source": "recommended", "desc": "Standard cost. Use when COGS is not stored at transaction level in F_Sales."}, {"name": "Supplier", "type": "Text", "source": "recommended", "desc": "Primary supplier name. Enables supplier-level product analysis."}, {"name": "IsActive", "type": "Boolean", "source": "recommended", "desc": "TRUE if product is currently active/listed. Filter to exclude discontinued products."}, {"name": "LaunchDate", "type": "Date", "source": "recommended", "desc": "Date product was first sold. Used to classify new vs existing products by launch cohort."}]}, {"table": "F_Targets", "emoji": "🎯", "desc": "F_Sales and KPI targets. One row per time period per rep or team. Used in achievement %, variance, and pipeline coverage formulas.", "note": "Granularity matters — if targets are monthly by rep, each row = one rep × one month. Do not relate to M_Date; filter by year/month columns instead.", "usedIn": ["sales", "dynamic", "finance", "time"], "cols": [{"name": "SalesTarget", "type": "Currency", "source": "formula", "desc": "Revenue target for the period. Used in Achievement % and Pipeline Coverage formulas."}, {"name": "MonthlyTarget", "type": "Currency", "source": "formula", "desc": "Monthly revenue target. Used in Remaining Target MTD and Required Daily Rate formulas."}, {"name": "QuotaAmount", "type": "Currency", "source": "formula", "desc": "Individual rep quota. Used in Quota Attainment % per Rep formula."}, {"name": "TargetRevenue", "type": "Currency", "source": "formula", "desc": "Target revenue — used in Variance vs Target formula. May be same as SalesTarget."}, {"name": "Year", "type": "Integer", "source": "recommended", "desc": "Target year. Used to filter targets to the correct period."}, {"name": "Month", "type": "Integer", "source": "recommended", "desc": "Target month 1–12. Combine with Year to identify the target period."}, {"name": "RepID", "type": "Text", "source": "recommended", "desc": "F_Sales rep ID. Relates targets to reps for individual quota attainment."}, {"name": "Region", "type": "Text", "source": "recommended", "desc": "Region or territory. Enables regional target vs actual comparison."}]}, {"table": "F_Forecast", "emoji": "📈", "desc": "Revenue forecast data. One row per period (and optionally per rep or region). Used in Dynamic M_Comparison engine.", "note": "Keep at the same granularity as F_Targets for simplest DAX. Relate to M_Date via a date column.", "usedIn": ["dynamic", "sales"], "cols": [{"name": "ForecastAmount", "type": "Currency", "source": "formula", "desc": "Forecast revenue for the period. Used as the third reference point in Dynamic M_Comparison."}, {"name": "ForecastDate", "type": "Date", "source": "recommended", "desc": "Date the forecast applies to. Connect to M_Date[Date] for period-matched calculations."}, {"name": "Year", "type": "Integer", "source": "recommended", "desc": "Forecast year. Used to filter to the correct annual forecast."}, {"name": "Month", "type": "Integer", "source": "recommended", "desc": "Forecast month 1–12. Enables monthly forecast vs actual comparison."}, {"name": "Version", "type": "Text", "source": "recommended", "desc": "Forecast version name (e.g. 'Q1 Reforecast'). Useful when multiple forecast versions exist."}]}, {"table": "F_Opportunities", "emoji": "🤝", "desc": "F_Sales pipeline / CRM opportunities. One row per opportunity. Used in pipeline, win rate, and sales cycle formulas.", "note": "Typically exported from a CRM (Salesforce, HubSpot, Dynamics). Relate CloseDate to M_Date.", "usedIn": ["sales"], "cols": [{"name": "Value", "type": "Currency", "source": "formula", "desc": "Opportunity value (expected revenue if won). Used in pipeline and weighted pipeline formulas."}, {"name": "Stage", "type": "Text", "source": "formula", "desc": "'Open', 'Won', 'Lost'. Must use these exact values or adjust formulas to match your stage names."}, {"name": "Probability", "type": "Decimal", "source": "formula", "desc": "Win probability 0.0–1.0. Multiplied by Value to get weighted pipeline."}, {"name": "CloseDate", "type": "Date", "source": "formula", "desc": "Date the deal was closed (won or lost). Connect to M_Date for period filtering."}, {"name": "CycleStartDate", "type": "Date", "source": "formula", "desc": "Date the opportunity was created. Used with CloseDate to calculate sales cycle length."}, {"name": "LostReason", "type": "Text", "source": "formula", "desc": "Reason for losing (e.g. 'Competition', 'Price', 'No Decision'). Used in Revenue Lost to Competition."}, {"name": "Source", "type": "Text", "source": "formula", "desc": "Lead source ('Marketing', 'Inbound', 'Outbound'). Used in Marketing Pipeline Created formula."}, {"name": "PipelineValue", "type": "Currency", "source": "formula", "desc": "Pipeline value used in Marketing Pipeline metric. Can be same column as Value."}, {"name": "OpportunityName", "type": "Text", "source": "recommended", "desc": "Deal name or description. Shown in opportunity detail tables."}, {"name": "RepID", "type": "Text", "source": "recommended", "desc": "Owning sales rep ID. Links to F_Sales table for rep-level pipeline analysis."}, {"name": "CustomerID", "type": "Text", "source": "recommended", "desc": "Account/customer ID. Links opportunities to the customer dimension."}]}, {"table": "F_GL", "emoji": "📒", "desc": "General Ledger transactions. One row per journal entry line. The source of truth for all P&L measures. Work with M_COA (chart of accounts).", "note": "Join F_GL to M_COA on AccountCode to enable category-based filtering. Store both actuals and budget entries here — differentiate with a DataType column.", "usedIn": ["finance"], "cols": [{"name": "Amount", "type": "Currency", "source": "formula", "desc": "Transaction amount. Credit amounts should be negative (or use a sign convention column). SUM(F_GL[Amount]) filtered by category = P&L lines."}, {"name": "AccountCode", "type": "Text", "source": "recommended", "desc": "Chart of accounts code. Foreign key to M_COA. Used to classify transactions into P&L categories."}, {"name": "PostingDate", "type": "Date", "source": "recommended", "desc": "Date the entry was posted. Connect to M_Date[Date] for period filtering."}, {"name": "CostCentre", "type": "Text", "source": "recommended", "desc": "Department or cost centre code. Enables departmental P&L breakdown."}, {"name": "Entity", "type": "Text", "source": "recommended", "desc": "Legal entity or company code. Required for multi-entity consolidations."}, {"name": "Description", "type": "Text", "source": "recommended", "desc": "Transaction description or narration. Useful for drilling into specific entries."}, {"name": "DataType", "type": "Text", "source": "recommended", "desc": "'Actual' or 'Budget'. Allows budget vs actual analysis in a single table."}]}, {"table": "M_COA", "emoji": "📋", "desc": "Chart of Accounts master table. One row per account. Maps account codes to P&L categories. Do not relate directly to M_Date — join through F_GL.", "note": "The Category values used in formulas: 'Revenue', 'COGS', 'Operating Expenses', 'EBITDA', 'Depreciation & Amortisation', 'Interest Expense', 'Interest Income', 'Tax'. Match these exactly or update the formulas.", "usedIn": ["finance"], "cols": [{"name": "Category", "type": "Text", "source": "formula", "desc": "High-level P&L category: 'Revenue', 'COGS', 'Operating Expenses', 'D&A', 'Interest Expense', 'Interest Income', 'Tax'. Used to filter F_GL amounts into P&L lines."}, {"name": "Subcategory", "type": "Text", "source": "formula", "desc": "Sub-classification within Category (e.g. 'Product F_Sales', 'Direct Labour', 'Admin & General'). Enables line-item P&L drill-down."}, {"name": "CostBehaviour", "type": "Text", "source": "formula", "desc": "'Variable' or 'Fixed'. Used in Contribution Margin and Break-Even Revenue formulas. Tag each account accordingly."}, {"name": "DataType", "type": "Text", "source": "formula", "desc": "'Actual' or 'Budget'. Used in Budget Variance % formula to separate budget rows from actuals within F_GL."}, {"name": "AccountCode", "type": "Text", "source": "recommended", "desc": "Primary key. Unique account code — matches F_GL[AccountCode] for the relationship."}, {"name": "AccountName", "type": "Text", "source": "recommended", "desc": "Human-readable account name. Shown in P&L drill-down tables."}, {"name": "PLOrder", "type": "Integer", "source": "recommended", "desc": "Sort order for P&L display (1=Revenue, 2=COGS…). Controls sequence in financial statement visuals."}, {"name": "IsActive", "type": "Boolean", "source": "recommended", "desc": "TRUE if account is currently in use. Filter to exclude deprecated accounts from visuals."}]}, {"table": "F_AR", "emoji": "📨", "desc": "Accounts Receivable — customer invoices. One row per invoice. Used in DSO, ageing, and collections analysis.", "note": "Status values used in formulas: 'Open', 'Overdue', 'Paid', 'Written Off'. Match these exactly or update the formulas. Do not relate to M_Date — filter by DueDate or PaidDate directly.", "usedIn": ["finance"], "cols": [{"name": "InvoiceAmount", "type": "Currency", "source": "formula", "desc": "Original invoice value before any payments. Used as the total receivable amount."}, {"name": "PaidAmount", "type": "Currency", "source": "formula", "desc": "Amount collected against this invoice. InvoiceAmount - PaidAmount = outstanding balance."}, {"name": "Status", "type": "Text", "source": "formula", "desc": "'Open', 'Overdue', 'Paid', 'Written Off'. Drives all AR status filters."}, {"name": "DueDate", "type": "Date", "source": "formula", "desc": "Payment due date based on agreed terms. Used to classify invoices as current vs overdue."}, {"name": "PaidDate", "type": "Date", "source": "formula", "desc": "Date payment was received. Used in bad debt write-off period filtering."}, {"name": "AgeBucket", "type": "Text", "source": "formula", "desc": "'0-30', '31-60', '61-90', '90+'. Pre-calculated ageing bucket — populate in Power Query based on DueDate vs today."}, {"name": "InvoiceDate", "type": "Date", "source": "recommended", "desc": "Date invoice was issued. Used as the starting point for DSO calculation."}, {"name": "CustomerID", "type": "Text", "source": "recommended", "desc": "Customer identifier. Links AR to customer dimension for customer-level AR analysis."}, {"name": "InvoiceNumber", "type": "Text", "source": "recommended", "desc": "Invoice reference number. Used for drill-through to individual invoice details."}]}, {"table": "F_AP", "emoji": "📤", "desc": "Accounts Payable — supplier invoices. One row per invoice. Used in DPO, payment rate, and working capital analysis.", "note": "Status values: 'Open', 'Overdue', 'Paid'. EarlyPaymentDiscount and DiscountCaptured columns are needed for the early payment discount formula.", "usedIn": ["finance"], "cols": [{"name": "InvoiceAmount", "type": "Currency", "source": "formula", "desc": "Original supplier invoice value. Used as the total payable amount."}, {"name": "PaidAmount", "type": "Currency", "source": "formula", "desc": "Amount paid against this invoice. InvoiceAmount - PaidAmount = outstanding balance."}, {"name": "Status", "type": "Text", "source": "formula", "desc": "'Open', 'Overdue', 'Paid'. Drives all AP status filters."}, {"name": "DueDate", "type": "Date", "source": "formula", "desc": "Payment due date. Used to identify overdue AP and calculate DPO."}, {"name": "PaidDate", "type": "Date", "source": "formula", "desc": "Date payment was made. Used in on-time payment rate calculation."}, {"name": "EarlyPaymentDiscount", "type": "Decimal", "source": "formula", "desc": "Available early payment discount as a rate (e.g. 0.02 = 2%). Used in discount capture formula."}, {"name": "DiscountCaptured", "type": "Boolean", "source": "formula", "desc": "TRUE if the early payment discount was actually taken."}, {"name": "SupplierID", "type": "Text", "source": "recommended", "desc": "Supplier identifier. Links to a Suppliers dimension for supplier-level AP analysis."}, {"name": "InvoiceDate", "type": "Date", "source": "recommended", "desc": "Date of the supplier invoice. Used as the starting point for DPO calculations."}, {"name": "InvoiceNumber", "type": "Text", "source": "recommended", "desc": "Supplier invoice reference. Used for drill-through to individual payable details."}]}, {"table": "M_Employees", "emoji": "👤", "desc": "Employee master table. One row per employee — including leavers (do not delete leavers, just update Status and LeaveDate). The core HR dimension.", "note": "Never delete leaver rows — they are needed for attrition calculations. Set Status='Left' and populate LeaveDate. All point-in-time headcount formulas rely on JoinDate and LeaveDate being accurate.", "usedIn": ["hr", "finance"], "cols": [{"name": "Status", "type": "Text", "source": "formula", "desc": "'Active', 'Inactive', 'Left'. Active = working now; Inactive = on leave; Left = terminated."}, {"name": "JoinDate", "type": "Date", "source": "formula", "desc": "Date employee joined. Used in all point-in-time headcount snapshot formulas."}, {"name": "LeaveDate", "type": "Date", "source": "formula", "desc": "Date employee left. Leave blank (null) for current employees — blank = still working."}, {"name": "LeaveReason", "type": "Text", "source": "formula", "desc": "'Voluntary' or 'Involuntary'. Drives voluntary vs involuntary attrition split."}, {"name": "Department", "type": "Text", "source": "formula", "desc": "Department name. Used in departmental attrition rate and HR ratio formulas."}, {"name": "Gender", "type": "Text", "source": "formula", "desc": "'Male', 'Female', 'Other'. Used in gender split headcount formula."}, {"name": "EmploymentType", "type": "Text", "source": "formula", "desc": "'Full-Time' or 'Part-Time'. Used in FT vs PT headcount split."}, {"name": "BandLevel", "type": "Text", "source": "formula", "desc": "Grade or band (e.g. 'L1', 'Manager', 'Director'). Used in salary by band analysis."}, {"name": "IsRegrettable", "type": "Boolean", "source": "formula", "desc": "TRUE if the leaver was flagged as a regrettable loss. Set at exit by HR manager."}, {"name": "EmployeeID", "type": "Text", "source": "recommended", "desc": "Primary key — unique employee identifier. Used in DISTINCTCOUNT for headcount."}, {"name": "EmployeeName", "type": "Text", "source": "recommended", "desc": "Full name. Used in employee detail tables and drill-throughs."}, {"name": "JobTitle", "type": "Text", "source": "recommended", "desc": "Job title or role name. Used in role-level analysis and leaver detail reports."}, {"name": "Location", "type": "Text", "source": "recommended", "desc": "Office or site location. Enables location-based headcount and attrition analysis."}, {"name": "ManagerID", "type": "Text", "source": "recommended", "desc": "Manager employee ID. Enables org hierarchy drill-down and manager-level reports."}, {"name": "ContractType", "type": "Text", "source": "recommended", "desc": "'Permanent', 'Fixed-Term', 'Contractor'. Enables workforce composition analysis."}]}, {"table": "F_Payroll", "emoji": "💷", "desc": "Payroll data. One row per employee per pay period. Contains salary and total cost data for HR financial analysis.", "note": "Relate to M_Employees via EmployeeID. TotalCost should include salary + employer NI + pension + benefits — not just gross pay.", "usedIn": ["hr"], "cols": [{"name": "BaseSalary", "type": "Currency", "source": "formula", "desc": "Annual base salary for the employee in this pay period. Used in average, median, min and max salary formulas."}, {"name": "TotalCost", "type": "Currency", "source": "formula", "desc": "All-in employment cost: salary + NI + pension + benefits. The true cost of a headcount."}, {"name": "EmployeeID", "type": "Text", "source": "recommended", "desc": "Foreign key to M_Employees. Links payroll records to the employee dimension."}, {"name": "PayPeriodDate", "type": "Date", "source": "recommended", "desc": "Date of the pay period (e.g. last day of month). Connect to M_Date for time filtering."}, {"name": "Bonus", "type": "Currency", "source": "recommended", "desc": "Bonus paid in this period. Track separately from base to analyse variable pay spend."}, {"name": "Pension", "type": "Currency", "source": "recommended", "desc": "Employer pension contribution. Included in TotalCost but useful to see separately."}, {"name": "NationalInsurance", "type": "Currency", "source": "recommended", "desc": "Employer NI contribution. Included in TotalCost but useful for compliance reporting."}]}, {"table": "F_Recruitment", "emoji": "🔍", "desc": "Recruitment pipeline. One row per vacancy/job opening. Tracks the full hiring process from open to filled.", "note": "Relate FilledDate and HireDate to M_Date for period-filtered recruitment reporting.", "usedIn": ["hr"], "cols": [{"name": "Status", "type": "Text", "source": "formula", "desc": "'Open', 'Filled', 'Cancelled'. Used in open vacancies count and vacancies filled formulas."}, {"name": "OpenDate", "type": "Date", "source": "formula", "desc": "Date vacancy was opened. Used with FilledDate to calculate Time to Fill."}, {"name": "FilledDate", "type": "Date", "source": "formula", "desc": "Date vacancy was successfully filled. Used in vacancies filled and time to fill formulas."}, {"name": "ApplicationDate", "type": "Date", "source": "formula", "desc": "Date candidate applied. Used with HireDate to calculate Time to Hire."}, {"name": "HireDate", "type": "Date", "source": "formula", "desc": "Date offer was accepted / employee started. Used in time to hire and onboarding formulas."}, {"name": "OfferMade", "type": "Boolean", "source": "formula", "desc": "TRUE when an offer was extended to a candidate."}, {"name": "OfferAccepted", "type": "Boolean", "source": "formula", "desc": "TRUE when the candidate accepted the offer. Used in offer acceptance rate."}, {"name": "CostPerHire", "type": "Currency", "source": "formula", "desc": "Total recruitment cost for this vacancy. Include agency fees, advertising, assessment centre costs."}, {"name": "Source", "type": "Text", "source": "formula", "desc": "'Internal' or 'External'. Used in internal hire rate formula."}, {"name": "RecruiterID", "type": "Text", "source": "formula", "desc": "Recruiter responsible for the vacancy. Used in hires per recruiter efficiency metric."}, {"name": "ProductivityDate", "type": "Date", "source": "formula", "desc": "Date manager marked new hire as fully productive. Used in days to productivity formula."}, {"name": "JobTitle", "type": "Text", "source": "recommended", "desc": "Title of the role being filled. Enables role-level time to fill analysis."}, {"name": "Department", "type": "Text", "source": "recommended", "desc": "Hiring department. Enables departmental recruitment analysis."}, {"name": "ReasonForVacancy", "type": "Text", "source": "recommended", "desc": "'New Role', 'Backfill', 'Growth'. Helps understand demand drivers."}]}, {"table": "F_Leave", "emoji": "🏖️", "desc": "Employee leave records. One row per leave booking/request. Tracks entitlement and days taken for absence analysis.", "note": "Include all leave types: Annual, Sick, Maternity, Paternity, Unpaid etc. in LeaveType. The Status column controls whether leave has been taken or is only booked.", "usedIn": ["hr"], "cols": [{"name": "DaysTaken", "type": "Decimal", "source": "formula", "desc": "Number of leave days taken in this record. Can be fractional (0.5 = half day)."}, {"name": "Entitlement", "type": "Decimal", "source": "formula", "desc": "Total leave entitlement for this employee in this period. Used in leave utilisation % formula."}, {"name": "LeaveType", "type": "Text", "source": "formula", "desc": "'Annual', 'Sick', 'Maternity', 'Paternity', 'Working Days'. Used to split leave by type."}, {"name": "Status", "type": "Text", "source": "formula", "desc": "'Taken', 'Booked', 'Cancelled'. Filter to 'Taken' for consumed leave counts."}, {"name": "EmployeeID", "type": "Text", "source": "recommended", "desc": "Foreign key to M_Employees. Links leave records to the employee."}, {"name": "StartDate", "type": "Date", "source": "recommended", "desc": "First day of the leave period. Used for time-period filtering of leave records."}, {"name": "EndDate", "type": "Date", "source": "recommended", "desc": "Last day of the leave period."}]}, {"table": "F_Absence", "emoji": "🤒", "desc": "Unplanned absence records. One row per absence spell. Separate from Leave table — this captures unplanned/sickness absence for Bradford Factor and absenteeism analysis.", "note": "Each distinct unplanned absence episode = one row with a unique SpellNumber. Multiple days in the same continuous spell share the same SpellNumber.", "usedIn": ["hr"], "cols": [{"name": "Days", "type": "Decimal", "source": "formula", "desc": "Number of working days lost in this absence spell."}, {"name": "EmployeeID", "type": "Text", "source": "formula", "desc": "Employee who was absent. Used with ALLEXCEPT in Bradford Factor formula."}, {"name": "SpellNumber", "type": "Integer", "source": "formula", "desc": "Unique identifier per absence episode. DISTINCTCOUNT of SpellNumber = number of separate spells for Bradford Factor (S)."}, {"name": "StartDate", "type": "Date", "source": "recommended", "desc": "First day of absence. Connect to M_Date for period filtering."}, {"name": "ReturnDate", "type": "Date", "source": "recommended", "desc": "Date employee returned to work."}, {"name": "Reason", "type": "Text", "source": "recommended", "desc": "Absence reason category (e.g. 'Sickness', 'Family Emergency'). Enables reason-based absence analysis."}]}, {"table": "F_Tickets", "emoji": "🎫", "desc": "Customer service / support tickets. One row per ticket. The core CS fact table.", "note": "Status values used in formulas: 'Open', 'Resolved', 'Closed', 'Escalated', 'Unresolvable'. Match these exactly or update the formulas.", "usedIn": ["customerservice"], "cols": [{"name": "Status", "type": "Text", "source": "formula", "desc": "'Open', 'Resolved', 'Closed', 'Escalated', 'Unresolvable'. Drives all ticket status filters."}, {"name": "CreatedDate", "type": "Date", "source": "formula", "desc": "Date/time ticket was created. Connect to M_Date for period analysis."}, {"name": "ResolvedDate", "type": "Date", "source": "formula", "desc": "Date/time ticket was resolved. Null if still open. Used in resolution time and SLA formulas."}, {"name": "AgentID", "type": "Text", "source": "formula", "desc": "Agent who handled the ticket. Used in per-agent performance analysis."}, {"name": "CSATScore", "type": "Integer", "source": "formula", "desc": "Customer satisfaction score 1–5. Leave blank (null) if customer did not respond — do not use 0 for no response."}, {"name": "FCR", "type": "Boolean", "source": "formula", "desc": "TRUE if the ticket was resolved in a single contact without reopening."}, {"name": "HandleTimeMinutes", "type": "Decimal", "source": "formula", "desc": "Total handling time in minutes (talk time + wrap time). Used in AHT calculation."}, {"name": "ResolutionTime", "type": "Decimal", "source": "formula", "desc": "Hours from creation to resolution. Pre-calculate in Power Query: DATEDIFF(CreatedDate, ResolvedDate, hours)."}, {"name": "SLATarget", "type": "Decimal", "source": "formula", "desc": "SLA target in hours for this ticket's priority level. Used in SLA compliance formulas."}, {"name": "EscalationFlag", "type": "Boolean", "source": "formula", "desc": "TRUE if ticket was escalated to a senior team."}, {"name": "ReopenFlag", "type": "Boolean", "source": "formula", "desc": "TRUE if this ticket was reopened after being marked resolved."}, {"name": "Channel", "type": "Text", "source": "formula", "desc": "'Email', 'Phone', 'Chat', 'Self-Service'. Used in channel mix analysis."}, {"name": "TicketID", "type": "Text", "source": "recommended", "desc": "Primary key — unique ticket identifier."}, {"name": "Priority", "type": "Text", "source": "recommended", "desc": "'P1', 'P2', 'P3' etc. Used to segment SLA analysis by severity."}, {"name": "ContactReason", "type": "Text", "source": "recommended", "desc": "Why the customer contacted — e.g. 'Billing', 'Technical', 'Returns'. Used in root cause analysis."}, {"name": "CustomerID", "type": "Text", "source": "recommended", "desc": "Customer identifier. Links tickets to the customer dimension for customer-level CS analysis."}]}, {"table": "M_Agents", "emoji": "🎧", "desc": "Customer service agent dimension. One row per agent. Used in agent CSAT ranking formula.", "note": "Relate to F_Tickets via AgentID. Keep agent demographic data here, not in the F_Tickets fact table.", "usedIn": ["customerservice"], "cols": [{"name": "AgentName", "type": "Text", "source": "formula", "desc": "Full agent name. Used in RANKX leaderboard labels for agent CSAT ranking."}, {"name": "AgentID", "type": "Text", "source": "recommended", "desc": "Primary key. Must match F_F_Tickets[AgentID] for the relationship."}, {"name": "Team", "type": "Text", "source": "recommended", "desc": "Agent's team or group. Enables team-level CS performance analysis."}, {"name": "StartDate", "type": "Date", "source": "recommended", "desc": "Date agent joined the CS team. Used to analyse performance by tenure."}]}, {"table": "F_Inventory", "emoji": "🏭", "desc": "F_Inventory snapshot table. One row per product per snapshot date. Capture a daily or weekly snapshot of stock levels rather than running transactions.", "note": "Most formulas filter to MAX(F_F_Inventory[SnapshotDate]) to get the current position. Ensure snapshots are taken consistently — gaps will cause incorrect 'current stock' readings.", "usedIn": ["inventory"], "cols": [{"name": "QtyOnHand", "type": "Integer", "source": "formula", "desc": "Units physically in stock at this snapshot date."}, {"name": "StockValue", "type": "Currency", "source": "formula", "desc": "Total value of stock at cost at this snapshot date."}, {"name": "QtyOnOrder", "type": "Integer", "source": "formula", "desc": "Units currently on purchase order but not yet received."}, {"name": "QtyReserved", "type": "Integer", "source": "formula", "desc": "Units already allocated to open orders but not yet shipped."}, {"name": "SnapshotDate", "type": "Date", "source": "formula", "desc": "Date of this stock snapshot. Formulas filter to MAX(SnapshotDate) to get the current position."}, {"name": "ProductID", "type": "Text", "source": "formula", "desc": "Foreign key to M_Products table. Enables product-level inventory analysis."}, {"name": "MinStockLevel", "type": "Integer", "source": "formula", "desc": "Minimum safety stock level. Trigger the stockout alert when QtyOnHand drops below this."}, {"name": "MaxStockLevel", "type": "Integer", "source": "formula", "desc": "Maximum holding level. Trigger overstock alert when QtyOnHand exceeds this."}, {"name": "ReorderPoint", "type": "Integer", "source": "formula", "desc": "Stock level that triggers a reorder. Calculated as: (Avg Daily F_Sales × Lead Time) + Safety Stock."}, {"name": "ExpiryDate", "type": "Date", "source": "formula", "desc": "Expiry date for perishable stock. Used in stock expiring within 30 days formula."}, {"name": "ShrinkageQty", "type": "Integer", "source": "formula", "desc": "Units lost to theft, damage, or admin error in this period. Used in shrinkage % formula."}, {"name": "OpeningQty", "type": "Integer", "source": "formula", "desc": "Opening stock quantity (start of period). Used as the denominator in shrinkage % formula."}, {"name": "PhysicalCount", "type": "Integer", "source": "formula", "desc": "Physical count result from a stock count exercise. Compared to QtyOnHand for accuracy %."}, {"name": "Location", "type": "Text", "source": "recommended", "desc": "Warehouse or bin location. Enables location-level stock analysis."}, {"name": "BatchNumber", "type": "Text", "source": "recommended", "desc": "Batch or lot number. Required for FIFO/FEFO costing and lot traceability."}]}, {"table": "F_Production", "emoji": "⚙️", "desc": "Production data. One row per production run or shift. Used in OEE, FPY, downtime, and output vs plan formulas.", "note": "All time columns (ScheduledMinutes, DowntimeMinutes etc.) should use the same unit — minutes is recommended. Do not mix hours and minutes.", "usedIn": ["operations"], "cols": [{"name": "UnitsProduced", "type": "Integer", "source": "formula", "desc": "Actual units produced in this run/shift. Used in OEE performance rate and production vs plan."}, {"name": "PlannedUnits", "type": "Integer", "source": "formula", "desc": "Planned output for this run/shift. Used in Production vs Plan % formula."}, {"name": "ScheduledMinutes", "type": "Integer", "source": "formula", "desc": "Total scheduled production time in minutes. The OEE denominator for Availability %."}, {"name": "DowntimeMinutes", "type": "Integer", "source": "formula", "desc": "Total downtime (planned + unplanned) in minutes. Used in Availability % formula."}, {"name": "PlannedDowntimeMinutes", "type": "Integer", "source": "formula", "desc": "Planned downtime (maintenance, changeovers) in minutes. Separate from unplanned."}, {"name": "UnplannedDowntimeMinutes", "type": "Integer", "source": "formula", "desc": "Unplanned downtime (breakdowns) in minutes. The more costly and actionable downtime type."}, {"name": "ReworkUnits", "type": "Integer", "source": "formula", "desc": "Units that required rework before passing quality. Used in FPY and Rework Rate % formulas."}, {"name": "DefectiveUnits", "type": "Integer", "source": "formula", "desc": "Units rejected as defective (including scrap). Used in Defect Rate PPM formula."}, {"name": "LabourHours", "type": "Decimal", "source": "formula", "desc": "Total labour hours worked in this run. Used in Units per Labour Hour productivity metric."}, {"name": "TheoreticalCapacity", "type": "Integer", "source": "formula", "desc": "Maximum possible units if running at 100% with zero downtime. Used in Capacity Utilisation %."}, {"name": "RunTimeHours", "type": "Decimal", "source": "formula", "desc": "Actual running time in hours (excluding downtime). Used in MTBF calculation."}, {"name": "ProductionDate", "type": "Date", "source": "recommended", "desc": "Date of this production run. Connect to M_Date for period filtering."}, {"name": "MachineID", "type": "Text", "source": "recommended", "desc": "Machine or work centre identifier. Enables machine-level OEE analysis."}, {"name": "ShiftID", "type": "Text", "source": "recommended", "desc": "Shift identifier (e.g. 'Day', 'Night'). Enables shift-level performance comparison."}]}, {"table": "F_Quality", "emoji": "✅", "desc": "Quality cost data. One row per period or quality event. Used in Cost of Poor Quality (COPQ) formula.", "note": "COPQ is split into three buckets: Internal Failure (rework, scrap), External Failure (warranty, returns), and Appraisal (inspection, testing).", "usedIn": ["operations"], "cols": [{"name": "InternalFailureCost", "type": "Currency", "source": "formula", "desc": "Cost of failures caught before delivery: rework, scrap, re-inspection. Usually the largest COPQ component."}, {"name": "ExternalFailureCost", "type": "Currency", "source": "formula", "desc": "Cost of failures after delivery: warranty claims, returns, complaint handling."}, {"name": "AppraisalCost", "type": "Currency", "source": "formula", "desc": "Cost of quality inspection and testing activities."}, {"name": "Period", "type": "Date", "source": "recommended", "desc": "Period date for this quality cost record. Connect to M_Date for time filtering."}, {"name": "ProductID", "type": "Text", "source": "recommended", "desc": "Product linked to the quality cost. Enables product-level COPQ analysis."}]}, {"table": "F_Maintenance", "emoji": "🔧", "desc": "Equipment maintenance and failure records. One row per maintenance event. Used in MTBF and MTTR reliability formulas.", "note": "One row per failure event, not per maintenance task. Multiple repair tasks for one failure = one row with the total RepairHours.", "usedIn": ["operations"], "cols": [{"name": "FailureCount", "type": "Integer", "source": "formula", "desc": "Number of failures in this record (usually 1). SUM gives total failures across all machines/periods for MTBF."}, {"name": "RepairHours", "type": "Decimal", "source": "formula", "desc": "Total hours taken to restore equipment after failure. Used in MTTR calculation."}, {"name": "FailureDate", "type": "Date", "source": "recommended", "desc": "Date of the failure event. Connect to M_Date for period-based reliability trending."}, {"name": "MachineID", "type": "Text", "source": "recommended", "desc": "Machine or equipment identifier. Enables machine-level MTBF and MTTR analysis."}, {"name": "FailureType", "type": "Text", "source": "recommended", "desc": "Category of failure (e.g. 'Mechanical', 'Electrical', 'Operator Error'). Used in root cause analysis."}]}, {"table": "F_Orders", "emoji": "📦", "desc": "Customer delivery orders. One row per delivery order. Used in OTD (On-Time Delivery) and OTIF formulas.", "note": "This is separate from F_Sales — Orders tracks the physical delivery fulfilment. Relate OrderDate to M_Date.", "usedIn": ["operations"], "cols": [{"name": "OrderDate", "type": "Date", "source": "formula", "desc": "Date the customer order was placed. Used in average lead time calculation."}, {"name": "CommittedDate", "type": "Date", "source": "formula", "desc": "Date promised to the customer for delivery. Used in OTD and OTIF compliance checks."}, {"name": "DeliveryDate", "type": "Date", "source": "formula", "desc": "Actual date delivered. Compared to CommittedDate for on-time assessment."}, {"name": "QtyOrdered", "type": "Integer", "source": "formula", "desc": "Units ordered by the customer. Used in OTIF (in-full) check."}, {"name": "QtyDelivered", "type": "Integer", "source": "formula", "desc": "Units actually delivered. Must equal QtyOrdered for OTIF to pass."}, {"name": "QtyShipped", "type": "Integer", "source": "formula", "desc": "Units shipped from stock. Used in Order Fill Rate % formula."}, {"name": "CustomerID", "type": "Text", "source": "recommended", "desc": "Customer who placed the order. Links deliveries to customer dimension."}, {"name": "OrderID", "type": "Text", "source": "recommended", "desc": "Primary key — unique order reference."}]}, {"table": "F_PurchaseOrders", "emoji": "🛒", "desc": "Supplier purchase orders. One row per PO. Used in Supplier On-Time Delivery % formula.", "note": "Relate to a Suppliers dimension via SupplierID for supplier-level performance analysis.", "usedIn": ["operations"], "cols": [{"name": "PromisedDelivery", "type": "Date", "source": "formula", "desc": "Delivery date promised by the supplier. Used in supplier OTD formula."}, {"name": "ActualDelivery", "type": "Date", "source": "formula", "desc": "Date the goods were actually received. Compared against PromisedDelivery for on-time assessment."}, {"name": "SupplierID", "type": "Text", "source": "recommended", "desc": "Supplier identifier. Enables supplier-level OTD performance ranking."}, {"name": "PODate", "type": "Date", "source": "recommended", "desc": "Date the purchase order was raised. Used to calculate supplier lead time."}, {"name": "POValue", "type": "Currency", "source": "recommended", "desc": "Total value of the purchase order. Enables spend-weighted supplier OTD analysis."}, {"name": "ProductID", "type": "Text", "source": "recommended", "desc": "Product being ordered. Links to M_Products dimension for product-level supply analysis."}]}, {"table": "F_Campaigns", "emoji": "📣", "desc": "Marketing campaign data. One row per campaign. Used in ROAS, ROI, and campaign-level performance formulas.", "note": "Relate CampaignDate to M_Date for time-period filtering. Revenue here should be attributed revenue from this specific campaign.", "usedIn": ["marketing"], "cols": [{"name": "Spend", "type": "Currency", "source": "formula", "desc": "Total spend for this campaign (ad budget + agency + production costs)."}, {"name": "Sale", "type": "Currency", "source": "formula", "desc": "Revenue attributed to this campaign. Used in Campaign ROI by Campaign formula."}, {"name": "CampaignID", "type": "Text", "source": "recommended", "desc": "Primary key — unique campaign identifier."}, {"name": "CampaignName", "type": "Text", "source": "recommended", "desc": "Campaign name. Shown in campaign performance tables."}, {"name": "CampaignDate", "type": "Date", "source": "recommended", "desc": "Campaign start date. Connect to M_Date for period filtering."}, {"name": "Channel", "type": "Text", "source": "recommended", "desc": "'Paid Search', 'Social', 'Email', 'Display'. Enables channel-level ROI comparison."}, {"name": "CampaignType", "type": "Text", "source": "recommended", "desc": "'Brand Awareness', 'Lead Gen', 'Retargeting'. Enables campaign type analysis."}, {"name": "Impressions", "type": "Integer", "source": "recommended", "desc": "Total impressions delivered. Used alongside spend for CPM calculation at campaign level."}, {"name": "Clicks", "type": "Integer", "source": "recommended", "desc": "Total clicks delivered. Used alongside spend for CPC calculation at campaign level."}]}, {"table": "F_Leads", "emoji": "🧲", "desc": "Marketing leads. One row per lead. Used in lead volume, conversion rate, CPL, and MQL formulas.", "note": "A lead becomes an MQL when it passes qualification criteria — update Stage to 'MQL' at that point. A converted lead should have Status = 'Converted'.", "usedIn": ["marketing"], "cols": [{"name": "LeadDate", "type": "Date", "source": "formula", "desc": "Date the lead was generated. Used with MIN/MAX(M_Date[Date]) for period filtering."}, {"name": "Status", "type": "Text", "source": "formula", "desc": "'Open', 'Converted', 'Disqualified'. 'Converted' = lead became a customer."}, {"name": "Stage", "type": "Text", "source": "formula", "desc": "'Lead', 'MQL', 'SQL', 'Opportunity'. 'MQL' triggers the MQL count formula."}, {"name": "LeadID", "type": "Text", "source": "recommended", "desc": "Primary key — unique lead identifier."}, {"name": "Source", "type": "Text", "source": "recommended", "desc": "Lead source: 'Paid Search', 'Organic', 'Referral', 'Event'. Used in CPL by channel analysis."}, {"name": "CampaignID", "type": "Text", "source": "recommended", "desc": "Campaign that generated the lead. Links leads to F_Campaigns for attribution."}, {"name": "ConvertedDate", "type": "Date", "source": "recommended", "desc": "Date the lead converted to a customer/opportunity."}]}, {"table": "F_DigitalAds", "emoji": "💻", "desc": "Digital advertising performance data. One row per ad/campaign per day. Used in CTR, CPC, and CPM formulas.", "note": "Typically imported from Google Ads, Meta Ads Manager, or LinkedIn Campaign Manager via Power Query connector.", "usedIn": ["marketing"], "cols": [{"name": "Clicks", "type": "Integer", "source": "formula", "desc": "Total clicks on the ad. Used in CTR % and CPC formulas."}, {"name": "Impressions", "type": "Integer", "source": "formula", "desc": "Total times the ad was displayed. Used in CTR % and CPM formulas."}, {"name": "Spend", "type": "Currency", "source": "formula", "desc": "Ad spend for this record. Used in CPC and CPM formulas."}, {"name": "Date", "type": "Date", "source": "recommended", "desc": "Date of the ad performance data. Connect to M_Date for period filtering."}, {"name": "Platform", "type": "Text", "source": "recommended", "desc": "'Google', 'Meta', 'LinkedIn', 'TikTok'. Enables platform-level performance comparison."}, {"name": "CampaignID", "type": "Text", "source": "recommended", "desc": "Links to the F_Campaigns table for campaign-level aggregation."}, {"name": "Conversions", "type": "Integer", "source": "recommended", "desc": "Number of conversions (e.g. form fills, purchases). Used for conversion rate analysis."}, {"name": "ConversionValue", "type": "Currency", "source": "recommended", "desc": "Revenue value of conversions. Used for ad-level ROAS calculation."}]}, {"table": "F_EmailCampaigns", "emoji": "📧", "desc": "Email marketing campaign data. One row per email send. Used in open rate, CTOR, and email performance formulas.", "note": "Typically imported from your email platform (Mailchimp, HubSpot, Klaviyo etc.). One row = one email campaign send.", "usedIn": ["marketing"], "cols": [{"name": "Sent", "type": "Integer", "source": "formula", "desc": "Total emails sent (after list cleaning — exclude hard bounces from denominator)."}, {"name": "Opens", "type": "Integer", "source": "formula", "desc": "Unique opens. Used in Open Rate % and CTOR % formulas."}, {"name": "Clicks", "type": "Integer", "source": "formula", "desc": "Unique clicks. Used in CTOR % formula (clicks ÷ opens)."}, {"name": "SendDate", "type": "Date", "source": "recommended", "desc": "Date the email was sent. Connect to M_Date for period filtering."}, {"name": "CampaignName", "type": "Text", "source": "recommended", "desc": "Email campaign name. Shown in email performance tables."}, {"name": "Bounces", "type": "Integer", "source": "recommended", "desc": "Hard bounces. Used to clean the Sent count and monitor list health."}, {"name": "Unsubscribes", "type": "Integer", "source": "recommended", "desc": "Unsubscribes from this send. Monitor for list hygiene and content relevance."}]}, {"table": "F_WebAnalytics", "emoji": "🌐", "desc": "Website analytics data. One row per session segment per day. Used in Bounce Rate % formula.", "note": "Typically imported from Google Analytics 4 via Power Query connector. Each row can represent a traffic source × date segment.", "usedIn": ["marketing"], "cols": [{"name": "Sessions", "type": "Integer", "source": "formula", "desc": "Total website sessions (visits). The denominator in Bounce Rate % formula."}, {"name": "Bounces", "type": "Integer", "source": "formula", "desc": "Sessions where the user left without any further interaction. Used in Bounce Rate % formula."}, {"name": "Date", "type": "Date", "source": "recommended", "desc": "Date of the traffic data. Connect to M_Date for period filtering."}, {"name": "Source", "type": "Text", "source": "recommended", "desc": "Traffic source (Organic, Paid, Direct, Referral, Social). Enables channel-level bounce rate analysis."}, {"name": "PageViews", "type": "Integer", "source": "recommended", "desc": "Total page views. Used in pages-per-session and engagement analysis."}, {"name": "Conversions", "type": "Integer", "source": "recommended", "desc": "Goal completions on the website. Used in website conversion rate formula."}]}, {"table": "M_PeriodSel", "emoji": "🔀", "desc": "Disconnected slicer table for Dynamic M_Comparison period selection. Contains 4 rows only. Create via DAX in Power BI.", "note": "Create in Power BI: Home → Enter Data → type the 4 values. Do NOT connect this table to any other table — it must be fully disconnected. Enable single-select on the slicer.", "usedIn": ["dynamic"], "cols": [{"name": "Period", "type": "Text", "source": "formula", "desc": "One of: 'MTD', 'QTD', 'YTD', 'Full Period'. These exact values are used in SELECTEDVALUE(M_PeriodSel[Period]) in all Dynamic formulas."}]}, {"table": "M_Comparison", "emoji": "🎯", "desc": "Disconnected slicer table for Dynamic M_Comparison reference selection. Contains 3 rows only. Create via DAX in Power BI.", "note": "Create in Power BI: Home → Enter Data → type the 3 values. Do NOT connect to any other table. Use as a button slicer (Format → Slicer Settings → Style: Tile/Buttons).", "usedIn": ["dynamic"], "cols": [{"name": "Reference", "type": "Text", "source": "formula", "desc": "One of: 'Last Year', 'Target', 'Forecast'. These exact values are used in SELECTEDVALUE(M_Comparison[Reference]) in all Dynamic Comparison formulas."}]}] as const;
